-- Exact independently accepted two-row Awakening final subset; all held Trainers excluded.
-- Private full metadata evidence, separate bounded constant-array reads.
BEGIN READ ONLY;
SET LOCAL statement_timeout = '20s';
SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=any(ARRAY['6ad6da5c-02cb-45e1-ab7a-2de25855dbf4'::uuid,'ab2c259c-353a-4317-b075-83f28a24fab2'::uuid]::uuid[]) ORDER BY identity LIMIT 3;
SELECT 'variants' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_variants t WHERE printing_id=any(ARRAY['6ad6da5c-02cb-45e1-ab7a-2de25855dbf4'::uuid,'ab2c259c-353a-4317-b075-83f28a24fab2'::uuid]::uuid[]) ORDER BY identity LIMIT 3;
SELECT 'names' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_names t WHERE printing_id=any(ARRAY['6ad6da5c-02cb-45e1-ab7a-2de25855dbf4'::uuid,'ab2c259c-353a-4317-b075-83f28a24fab2'::uuid]::uuid[]) ORDER BY identity LIMIT 5;
SELECT 'sets' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.sets t WHERE id='a15481a7-410b-4a98-8695-3bba0db9d226'::uuid ORDER BY identity LIMIT 2;
SELECT 'assets' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.assets t WHERE printing_id=any(ARRAY['6ad6da5c-02cb-45e1-ab7a-2de25855dbf4'::uuid,'ab2c259c-353a-4317-b075-83f28a24fab2'::uuid]::uuid[]) OR variant_id=any(ARRAY['c1935cc0-315e-472d-ac8d-65a2da94674c'::uuid,'c563902f-3ed5-41c6-8289-60dbdc121a5b'::uuid]::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id='a15481a7-410b-4a98-8695-3bba0db9d226'::uuid) ORDER BY identity LIMIT 9;
SELECT 'links' AS scope,catalogue_version_id::text||':'||asset_id::text AS identity,to_jsonb(t) AS payload FROM catalog.catalogue_version_assets t WHERE printing_id=any(ARRAY['6ad6da5c-02cb-45e1-ab7a-2de25855dbf4'::uuid,'ab2c259c-353a-4317-b075-83f28a24fab2'::uuid]::uuid[]) OR variant_id=any(ARRAY['c1935cc0-315e-472d-ac8d-65a2da94674c'::uuid,'c563902f-3ed5-41c6-8289-60dbdc121a5b'::uuid]::uuid[]) OR asset_id IN (SELECT id FROM catalog.assets WHERE printing_id=any(ARRAY['6ad6da5c-02cb-45e1-ab7a-2de25855dbf4'::uuid,'ab2c259c-353a-4317-b075-83f28a24fab2'::uuid]::uuid[]) OR variant_id=any(ARRAY['c1935cc0-315e-472d-ac8d-65a2da94674c'::uuid,'c563902f-3ed5-41c6-8289-60dbdc121a5b'::uuid]::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id='a15481a7-410b-4a98-8695-3bba0db9d226'::uuid)) OR (printing_id IS NULL AND variant_id IS NULL AND set_id='a15481a7-410b-4a98-8695-3bba0db9d226'::uuid) ORDER BY identity LIMIT 9;
SELECT 'sources' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM ingest.sources t WHERE code='scrydex' ORDER BY identity LIMIT 2;
ROLLBACK;
